VF=["Verdadeiro","Falso"]
T=[
# ---------- Temperatura e escalas (tm) ----------
("tm","O que a temperatura de um corpo mede?",["O grau de agitação das partículas que formam o corpo.","A quantidade total de calor guardada no corpo.","A massa do corpo.","A cor do corpo."],0,"Pense no movimento das moléculas.","A temperatura está ligada à energia cinética média de agitação das partículas. Quanto mais agitadas, maior a temperatura.",{}),
("tm","Qual é a diferença entre calor e temperatura?",["Calor é energia em trânsito por diferença de temperatura; temperatura mede o grau de agitação das partículas.","São a mesma coisa.","Calor mede o grau de agitação; temperatura é energia em trânsito.","Calor só existe em corpos quentes e temperatura só em corpos frios."],0,"Um é energia que passa; o outro é uma medida.","Calor é a energia que passa de um corpo para outro quando há diferença de temperatura. A temperatura mede o estado de agitação das partículas.",{}),
("tm","Em que sentido o calor flui espontaneamente?",["Do corpo de maior temperatura para o de menor temperatura.","Do corpo de menor para o de maior temperatura.","Do corpo de maior massa para o de menor massa.","Sempre do sólido para o líquido."],0,"Pense em uma xícara quente sobre a mesa.","O calor flui espontaneamente do corpo mais quente para o mais frio até o equilíbrio térmico.",{}),
("tm","O que significa dizer que dois corpos estão em equilíbrio térmico?",["Eles têm a mesma temperatura e não trocam calor entre si.","Eles têm a mesma massa.","Eles têm o mesmo calor guardado.","Um deles perdeu todo o calor."],0,"Depois de algum tempo em contato, o que acontece com as temperaturas?","No equilíbrio térmico as temperaturas se igualam, e o fluxo líquido de calor cessa.",{}),
("tm","Verdadeiro ou falso: na escala Celsius, a água ferve a 100 °C e congela a 0 °C ao nível do mar.",VF,0,"São os pontos fixos da escala.","Os pontos fixos da escala Celsius são 0 °C (fusão do gelo) e 100 °C (ebulição da água) à pressão normal.",{"v":1,"f":"escalas"}),
("tm","Qual é a relação entre a escala Kelvin e a Celsius?",["T (K) = θ (°C) + 273","T (K) = θ (°C) − 273","T (K) = 1,8 · θ (°C) + 32","T (K) = θ (°C) · 273"],0,"O zero absoluto é −273 °C.","A conversão usada é T = θ + 273. Assim 0 °C corresponde a 273 K.",{"f":"escalas"}),
("tm","O zero absoluto (0 K) corresponde, aproximadamente, a:",["−273 °C","0 °C","−100 °C","273 °C"],0,"É a menor temperatura possível.","Pela relação T = θ + 273, 0 K equivale a cerca de −273 °C.",{}),
("tm","Qual é a conversão entre Celsius (C) e Fahrenheit (F)?",["C/5 = (F − 32)/9","C/9 = (F − 32)/5","C = F − 32","C/5 = F/9"],0,"A água congela a 0 °C = 32 °F e ferve a 100 °C = 212 °F.","A razão entre variações é 5 para 9: C/5 = (F − 32)/9.",{"f":"escalas"}),
("tm","Uma variação de temperatura de 10 °C corresponde, na escala Kelvin, a uma variação de:",["10 K","283 K","263 K","18 K"],0,"As escalas têm o mesmo tamanho de grau.","Os intervalos de 1 °C e 1 K são iguais. Só o ponto de partida é diferente.",{}),
("tm","Um termômetro clínico de mercúrio funciona porque o mercúrio:",["Dilata quando a temperatura aumenta.","Fica mais pesado quando esquenta.","Muda de cor.","Congela perto do corpo."],0,"Pense no que ocorre com o volume do líquido.","O mercúrio dilata de modo regular com a temperatura, e a altura da coluna indica o valor medido.",{}),
("tm","A temperatura de 300 K corresponde a quantos graus Celsius?",["27 °C","573 °C","−573 °C","300 °C"],0,"θ = T − 273.","θ = 300 − 273 = 27 °C.",{"c":1}),
("tm","Qual é a temperatura, em °C, correspondente a 68 °F?",["20 °C","36 °C","40 °C","68 °C"],0,"C/5 = (F − 32)/9.","C/5 = (68 − 32)/9 = 4, então C = 20 °C.",{"c":1}),
# ---------- Dilatação térmica (dl) ----------
("dl","O que acontece, em geral, com as dimensões de um sólido quando ele é aquecido?",["Elas aumentam (dilatação).","Elas diminuem.","Ficam sempre iguais.","Só a massa aumenta."],0,"As partículas vibram mais e ocupam mais espaço.","Com o aquecimento a agitação aumenta e o corpo ocupa mais espaço: ocorre a dilatação térmica.",{}),
("dl","Por que há pequenos vãos entre os trilhos de uma ferrovia?",["Para permitir que os trilhos dilatem no calor sem se deformar.","Para economizar aço.","Para facilitar a limpeza.","Para o trem andar mais rápido."],0,"Pense em um dia muito quente.","Se não houvesse folga, a dilatação deformaria os trilhos nos dias quentes.",{}),
("dl","A expressão da dilatação linear de uma barra é:",["ΔL = L₀ · α · Δθ","ΔL = L₀ + α + Δθ","ΔL = α / (L₀ · Δθ)","ΔL = L₀ · Δθ / α"],0,"A variação do comprimento é proporcional ao comprimento inicial e à variação de temperatura.","A variação de comprimento é ΔL = L₀·α·Δθ, em que α é o coeficiente de dilatação linear.",{}),
("dl","Verdadeiro ou falso: o coeficiente de dilatação superficial (β) é, aproximadamente, o dobro do linear (α).",VF,0,"Em duas dimensões, a dilatação conta duas vezes.","Para sólidos isotrópicos, β ≈ 2α e o volumétrico γ ≈ 3α.",{"v":1}),
("dl","Se uma chapa metálica com um furo é aquecida, o que acontece com o tamanho do furo?",["Ele aumenta, como se fosse feito do mesmo material da chapa.","Ele diminui.","Ele não muda.","Ele desaparece."],0,"O furo dilata como o material que o cerca.","O furo se comporta como se fosse preenchido pelo material da chapa e, por isso, aumenta com o aquecimento.",{}),
("dl","Por que uma tampa metálica emperrada de um vidro pode ser solta passando-a sob água quente?",["Porque o metal dilata mais que o vidro e a tampa se afrouxa.","Porque a água dissolve a tampa.","Porque o vidro encolhe.","Porque a água lubrifica a rosca, sem relação com a temperatura."],0,"Compare os coeficientes de dilatação do metal e do vidro.","O metal costuma ter maior coeficiente de dilatação que o vidro, então a tampa dilata mais e solta.",{}),
("dl","Um termostato bimetálico usa duas lâminas de metais diferentes unidas. Ele funciona porque:",["Os dois metais dilatam de modo diferente e a lâmina se curva.","Os dois metais derretem juntos.","Um dos metais não dilata nunca.","A lâmina fica mais pesada."],0,"Coeficientes diferentes causam curvatura.","Com o aquecimento, o metal de maior coeficiente dilata mais, e a lâmina se curva, abrindo ou fechando um circuito.",{}),
("dl","Qual é o comportamento anômalo da água entre 0 °C e 4 °C?",["O volume diminui com o aquecimento, e a água tem a maior densidade a 4 °C.","O volume aumenta sempre.","A água não muda de volume.","A água congela a 4 °C."],0,"É por isso que lagos congelam de cima para baixo.","Entre 0 °C e 4 °C a água se contrai ao ser aquecida. A 4 °C a densidade é máxima.",{}),
("dl","Por que o gelo se forma primeiro na superfície de lagos de países frios, preservando a vida embaixo?",["Porque a água a 4 °C é a mais densa e fica no fundo, e o gelo é menos denso e flutua.","Porque o fundo é mais frio.","Porque a água do fundo congela primeiro.","Porque o gelo é mais denso que a água."],0,"Relacione densidade e dilatação anômala.","A água mais fria (perto de 0 °C) e o gelo ficam em cima, e a água a 4 °C, mais densa, fica no fundo.",{}),
("dl","Verdadeiro ou falso: em um líquido, a dilatação aparente observada em um frasco depende também da dilatação do frasco.",VF,0,"O frasco também dilata.","O líquido e o recipiente dilatam. A dilatação aparente do líquido é a real menos a do recipiente.",{"v":1}),
("dl","Uma barra de 2 m, com α = 1,2 × 10⁻⁵ °C⁻¹, é aquecida em 50 °C. Qual é o aumento de comprimento?",["1,2 mm","0,12 mm","12 mm","1,2 m"],0,"ΔL = L₀·α·Δθ.","ΔL = 2 × 1,2 × 10⁻⁵ × 50 = 1,2 × 10⁻³ m = 1,2 mm.",{"c":1}),
("dl","Uma placa tem área de 1 m² a 20 °C. Sabendo que β = 2,4 × 10⁻⁵ °C⁻¹, qual é a variação de área ao ser aquecida a 120 °C?",["2,4 × 10⁻³ m²","2,4 × 10⁻⁵ m²","2,4 m²","1,2 × 10⁻³ m²"],0,"ΔA = A₀·β·Δθ.","ΔA = 1 × 2,4 × 10⁻⁵ × 100 = 2,4 × 10⁻³ m².",{"c":1}),
# ---------- Calorimetria (cl) ----------
("cl","A caloria (cal) é uma unidade de:",["Energia (calor).","Temperatura.","Massa.","Potência."],0,"1 cal ≈ 4,2 J.","A caloria mede energia. No SI, a unidade de energia é o joule: 1 cal ≈ 4,2 J.",{}),
("cl","O calor específico de uma substância indica:",["A quantidade de calor necessária para variar em 1 °C a temperatura de 1 g da substância.","A temperatura em que ela derrete.","A massa de 1 cm³ da substância.","A rapidez com que ela esfria sempre."],0,"É o valor de c em Q = m·c·Δθ.","O calor específico (c) é a quantidade de calor por unidade de massa para variar 1 °C a temperatura.",{}),
("cl","Qual é a expressão do calor sensível?",["Q = m · c · Δθ","Q = m · L","Q = m / (c · Δθ)","Q = c / (m · Δθ)"],0,"Calor que muda a temperatura, sem mudar de estado.","O calor sensível é Q = m·c·Δθ. O calor latente (mudança de estado) é Q = m·L.",{}),
("cl","Qual é o calor específico aproximado da água líquida?",["1 cal/g·°C","0,1 cal/g·°C","10 cal/g·°C","80 cal/g·°C"],0,"É o valor usado como referência.","A água tem calor específico de cerca de 1 cal/(g·°C), um valor alto em relação a outras substâncias.",{}),
("cl","Por que, na praia, a areia esquenta mais depressa que a água do mar?",["Porque a areia tem calor específico menor que o da água.","Porque a água não recebe sol.","Porque a areia é mais densa que o mar.","Porque a água tem calor específico menor."],0,"Compare c da areia e da água.","Com a mesma energia, a substância de menor calor específico varia mais a temperatura.",{}),
("cl","O que é capacidade térmica de um corpo?",["A quantidade de calor necessária para variar em 1 °C a temperatura do corpo todo.","A quantidade de água que ele contém.","A temperatura máxima que ele suporta.","A massa dividida pelo volume."],0,"C = Q/Δθ = m·c.","A capacidade térmica é C = m·c, o calor necessário para variar a temperatura do corpo em 1 °C.",{}),
("cl","Dois corpos de materiais diferentes recebem a mesma quantidade de calor e têm a mesma massa. Qual esquenta mais?",["O de menor calor específico.","O de maior calor específico.","Os dois esquentam igual.","O mais claro."],0,"Δθ = Q/(m·c).","Para Q e m iguais, Δθ é maior quando c é menor.",{}),
("cl","Em um sistema isolado, dois corpos trocam calor até o equilíbrio. Vale que:",["A soma dos calores trocados é zero (o que um perde, o outro ganha).","O calor desaparece.","Os dois ficam com a mesma massa.","Os dois ficam com a mesma capacidade térmica."],0,"Conservação de energia.","Em um sistema isolado, ΣQ = 0: o calor cedido por um é igual ao absorvido pelo outro.",{}),
("cl","Verdadeiro ou falso: 1 cal equivale, aproximadamente, a 4,2 J.",VF,0,"É o equivalente mecânico do calor.","Uma caloria corresponde a cerca de 4,2 joules.",{"v":1}),
("cl","Qual é a quantidade de calor necessária para aquecer 200 g de água de 20 °C a 50 °C? (c = 1 cal/g·°C)",["6000 cal","600 cal","4000 cal","10 000 cal"],0,"Q = m·c·Δθ.","Q = 200 × 1 × (50 − 20) = 6000 cal.",{"c":1}),
("cl","Um corpo de capacidade térmica 50 cal/°C recebe 1000 cal. Qual é a variação de temperatura?",["20 °C","50 °C","0,05 °C","2 °C"],0,"Δθ = Q / C.","Δθ = 1000 / 50 = 20 °C.",{"c":1}),
("cl","Misturam-se 100 g de água a 80 °C com 100 g de água a 20 °C, em um recipiente isolado. Qual é a temperatura final?",["50 °C","60 °C","40 °C","100 °C"],0,"Massas iguais e mesmo c: média das temperaturas.","m·c·(80 − T) = m·c·(T − 20), então T = 50 °C.",{"c":1}),
# ---------- Mudanças de estado (me) ----------
("me","Qual é o nome da passagem de sólido para líquido?",["Fusão.","Solidificação.","Vaporização.","Condensação."],0,"É o que acontece com o gelo no calor.","Sólido para líquido é fusão. Líquido para sólido é solidificação.",{}),
("me","Qual é o nome da passagem de líquido para gás?",["Vaporização.","Fusão.","Sublimação.","Solidificação."],0,"Inclui a evaporação e a ebulição.","Líquido para gás é vaporização. Gás para líquido é condensação.",{}),
("me","Durante a fusão do gelo, a 0 °C, enquanto ainda há gelo e água, a temperatura:",["Permanece constante, embora o gelo receba calor.","Aumenta continuamente.","Diminui.","Oscila sem regra."],0,"Pense no patamar do gráfico de aquecimento.","Durante a mudança de estado de uma substância pura, a temperatura fica constante. O calor é usado para mudar o estado.",{"f":"curva"}),
("me","O calor latente é:",["A quantidade de calor por unidade de massa necessária para mudar o estado, sem variar a temperatura.","A quantidade de calor que muda a temperatura de 1 g em 1 °C.","A temperatura em que ocorre a ebulição.","A energia guardada no corpo."],0,"Q = m·L.","O calor latente L é o calor por unidade de massa que provoca a mudança de estado a temperatura constante.",{}),
("me","Qual é o calor latente de fusão do gelo, aproximadamente?",["80 cal/g","540 cal/g","1 cal/g","0,5 cal/g"],0,"Valor usado nos exercícios de gelo.","O calor latente de fusão do gelo é de cerca de 80 cal/g. O de vaporização da água é de cerca de 540 cal/g.",{}),
("me","Qual é a diferença entre evaporação e ebulição?",["A evaporação ocorre na superfície, em qualquer temperatura; a ebulição ocorre em toda a massa, em temperatura definida.","São o mesmo fenômeno.","A ebulição ocorre só em sólidos.","A evaporação ocorre só em 100 °C."],0,"Pense em roupa secando no varal e água na panela.","A evaporação é lenta e superficial. A ebulição é rápida, em todo o líquido, a uma temperatura que depende da pressão.",{}),
("me","Por que a água ferve a uma temperatura menor em locais de grande altitude?",["Porque a pressão atmosférica é menor.","Porque a gravidade é maior.","Porque a água é mais pura.","Porque o ar é mais quente."],0,"Pressão menor, ebulição mais fácil.","Com pressão menor, as moléculas escapam mais facilmente, e o ponto de ebulição diminui.",{}),
("me","Verdadeiro ou falso: a sublimação é a passagem direta do estado sólido para o gasoso, como a naftalina.",VF,0,"Sem passar pelo líquido.","Na sublimação, o sólido vira gás diretamente. O gelo-seco e a naftalina são exemplos.",{"v":1}),
("me","No gráfico de aquecimento da água, os trechos horizontais indicam:",["Mudança de estado, com temperatura constante.","Aquecimento do gelo.","Resfriamento da água.","Erro de medição."],0,"Quanto calor é usado para mudar o estado?","Nos patamares, o calor recebido é empregado na mudança de estado (fusão e ebulição) e a temperatura fica constante.",{"f":"curva"}),
("me","Por que suar ajuda a resfriar o corpo?",["Porque a evaporação do suor retira calor da pele.","Porque o suor aquece o corpo.","Porque o suor é gelado.","Porque a pele absorve a água."],0,"A evaporação consome energia.","Para evaporar, o suor absorve calor da pele, e o corpo esfria.",{}),
("me","Qual é a quantidade de calor para fundir 50 g de gelo a 0 °C? (L = 80 cal/g)",["4000 cal","400 cal","130 cal","40 000 cal"],0,"Q = m·L.","Q = 50 × 80 = 4000 cal.",{"c":1}),
("me","Quanto calor é necessário para transformar 10 g de água a 100 °C em vapor a 100 °C? (L = 540 cal/g)",["5400 cal","540 cal","54 cal","54 000 cal"],0,"Q = m·L.","Q = 10 × 540 = 5400 cal.",{"c":1}),
# ---------- Propagação do calor (pc) ----------
("pc","Quais são as três formas de propagação do calor?",["Condução, convecção e irradiação.","Fusão, ebulição e sublimação.","Dilatação, contração e compressão.","Reflexão, refração e difração."],0,"Uma delas acontece até no vácuo.","O calor se propaga por condução, convecção e irradiação.",{}),
("pc","A condução térmica ocorre principalmente:",["Em sólidos, pela vibração das partículas, sem transporte de matéria.","Em líquidos, com correntes.","No vácuo.","Somente em gases."],0,"Pense em uma colher de metal em uma panela quente.","Na condução, a energia passa de partícula a partícula, sem que haja deslocamento do material.",{}),
("pc","A convecção térmica é o transporte de calor:",["Por movimento de massa do fluido (correntes de convecção).","Por ondas eletromagnéticas.","Apenas em sólidos.","Somente no vácuo."],0,"O ar quente sobe e o frio desce.","Em líquidos e gases, as porções quentes (menos densas) sobem e as frias descem, formando correntes.",{}),
("pc","A irradiação térmica é a propagação de calor por:",["Ondas eletromagnéticas, inclusive no vácuo.","Contato direto entre sólidos.","Correntes de líquido.","Dilatação do material."],0,"É como o calor do Sol chega à Terra.","A irradiação ocorre por ondas eletromagnéticas e não precisa de meio material.",{}),
("pc","Como o calor do Sol chega até a Terra?",["Por irradiação.","Por condução.","Por convecção.","Por dilatação."],0,"Entre o Sol e a Terra há vácuo.","No vácuo só é possível a irradiação.",{}),
("pc","Por que o congelador fica na parte de cima da geladeira?",["Porque o ar frio desce e forma correntes de convecção que resfriam todo o interior.","Porque o frio sobe.","Porque a parte de baixo é mais quente por condução.","Por razões apenas estéticas."],0,"Ar frio é mais denso.","O ar frio, mais denso, desce, e o ar mais quente sobe, formando correntes que resfriam toda a geladeira.",{}),
("pc","Por que um cabo de panela costuma ser feito de madeira ou plástico?",["Porque são isolantes térmicos e conduzem mal o calor.","Porque são bons condutores.","Porque derretem fácil.","Porque são mais caros."],0,"Pense em segurar a panela sem se queimar.","Madeira e plástico são maus condutores de calor, e por isso protegem a mão.",{}),
("pc","Por que a garrafa térmica mantém o líquido quente por muito tempo?",["Tem paredes duplas espelhadas com vácuo entre elas, reduzindo condução, convecção e irradiação.","Porque produz calor.","Porque o vidro é um excelente condutor.","Porque a tampa é de metal."],0,"O vácuo não conduz nem convecta.","O vácuo entre as paredes impede condução e convecção, e o espelhamento reduz a irradiação.",{}),
("pc","Verdadeiro ou falso: os metais são, em geral, bons condutores de calor.",VF,0,"Pense em uma colher de metal na sopa quente.","Os metais têm elétrons livres e conduzem bem o calor e a eletricidade.",{"v":1}),
("pc","Por que, no inverno, usamos roupas de lã, que prendem ar entre as fibras?",["O ar parado é um isolante térmico e reduz a perda de calor do corpo.","A lã produz calor.","O ar conduz bem o calor.","A lã é um ótimo condutor."],0,"O ar é mau condutor.","O ar retido nas fibras é um mau condutor, e isso reduz a perda de calor.",{}),
("pc","Por que objetos escuros esquentam mais ao sol do que os claros?",["Porque absorvem mais radiação e refletem menos.","Porque refletem mais radiação.","Porque são mais densos.","Porque têm calor específico menor sempre."],0,"Pense numa camiseta preta.","Superfícies escuras absorvem mais a radiação incidente, e as claras refletem mais.",{}),
("pc","Em uma noite fria, uma pessoa encosta a mão em um piso de cerâmica e em um tapete, ambos à mesma temperatura. A cerâmica parece mais fria porque:",["Conduz melhor o calor e retira calor da mão mais depressa.","Está de fato mais fria que o tapete.","O tapete produz calor.","A cerâmica irradia mais."],0,"Sensação não é temperatura.","Os dois estão à mesma temperatura, mas a cerâmica conduz melhor e retira calor mais rápido da mão.",{}),
]
